// The library catalog at three levels: styles, worlds and recipes (library/arsenal/, generated by
// tools/channel-learner/arsenal.mjs; never edited by hand). Design: docs/superpowers/specs/2026-11-24-library-three-levels-design.md.
// Among the recipes, pieces are runnable code (library/pieces/<name>.jsx): one file each, called by name.
// One tool, ae_arsenal, with four actions:
//   browse  a level as labelled tiles, a page at a time: id, name and provides under each still
//   find    by job, a ranked shortlist for one beat, pieces first (product/arsenal-catalog-design.md, "The query"); by
//           level and/or provides, entries across levels; or by plain words (query), pieces first
//   get     any entry by id: a piece's call, a recipe's full text, or a style's document; a warning when a pinned
//           revision is not the shipped one
//   jobs    the job vocabulary with one-line definitions, and the provides vocabulary
// The job ranking and refusals for written recipes are the same as tools/channel-learner/catalog.mjs findTechniques
// (their tests mirror it); pieces exist only in the shipped catalog and rank ahead of recipes on the same job.
// Offline: reads only hashed library documents and the stills the catalog names; never contacts After Effects.
import { readFileSync, realpathSync } from "node:fs";
import { createHash } from "node:crypto";
import path from "node:path";
import { z } from "zod";
import { PACKAGE_ROOT } from "../config.js";
import { errorResult } from "../errors.js";
import { defineTool, jsonResult } from "./define-tool.js";
import { libraryDocumentReply, readLibraryEntry } from "./library.js";
import type { ToolContent, ToolResult } from "./types.js";

const LIBRARY = path.resolve(PACKAGE_ROOT, "../library");

export const LEVELS = ["style", "world", "recipe"] as const;
export type Level = (typeof LEVELS)[number];

/** How to call a piece: the file to load, the call, its options, what it returns, a short example and notes. */
export type PieceCall = {
  load: string; signature: string; options: Array<{ name: string; text: string }>; returns: string | null; example: string; notes: string[];
};
/**
 * One catalog entry at any level. A recipe has a job (or is a build aid); a piece is a recipe that is runnable code;
 * a style entry is a style or a world.
 */
export type ArsenalEntry = {
  id: string; revision: string; name: string; line: string;
  status: "proven" | "unproven"; kind: "technique" | "build-aid" | "unmatched" | "style" | "piece";
  level: Level;
  /** Other levels the entry serves (a world that is also a style). */
  also_level?: Level[];
  /** What the entry gives a piece, "key" or "key: word", from the catalog's provides vocabulary. */
  provides: string[];
  cost: { renderer: "classic" | "advanced-3d" | "blender"; seconds_per_frame?: number; measured?: string };
  composes: string[];
  shelf: "shipped" | "user";
  good_for?: string;
  /** Why an entry has no still; browse hides it unless asked. */
  no_still?: string;
  job: string | null; support: string[]; mood: string[]; needs: string[];
  duration: number | string | null; motion: string | null; difficulty: number | null; taught_by: number;
  /** Only on a variant: the id of the entry it is a variant of. */
  variant_of?: string;
  /** The ids of this entry's variants; empty when it has none. */
  variants: string[];
  section: { document: string; heading: string | null };
  still: { path: string; sha256: string } | null;
  /**
   * Styles only: the style block the pieces read (library/pieces/styles/<block>.json, PCS.use('<block>')); role house
   * (the default) or example for the blocks that are entries of their own; what is still open in it.
   */
  block?: string; role?: "house" | "example"; default?: boolean; open?: string[];
  /** Pieces only: when to reach for it, the other pieces it loads itself, and how to call it. */
  use_for?: string;
  requires?: string[];
  call?: PieceCall;
};
/** A recipe entry: the name the job query and its tests use. */
export type ArsenalRecipe = ArsenalEntry;
export type ArsenalCatalog = {
  vocab: string; version: string; jobs: string[];
  levels?: readonly Level[]; provides?: Record<string, string[]>;
  entries: ArsenalEntry[];
};

export type BeatAsk = {
  vocab?: string; job: string; support?: string[]; duration?: number; takeaway?: string; mood?: string[];
  assets?: Record<string, unknown> | string[] | "none";
  constraints?: { aspect?: string; theme?: string; palette?: string; status?: "proven" | "any" };
  exclude?: string[]; limit?: number;
};
export type Candidate = Pick<ArsenalRecipe, "id" | "revision" | "name" | "line" | "status" | "needs" | "duration" | "motion" | "section">
  & { still: string | null; fit: string; variants?: string[]; kind?: "piece"; call?: string };
export type FindAnswer = { vocab: string; version: string; results: Candidate[]; relaxed?: string[] };

/** A refusal the asker can act on (an unknown job, another vocab); the message says what is valid. */
export class ArsenalRefusal extends Error {}

// Which recipe `needs` each kind of beat asset can meet. A need not listed (type, shapes, 3D camera, none...) is built
// inside After Effects and always passes. screen and footage both meet footage; photo meets photo and illustration;
// library (a rendered cast) meets photo, illustration and character; logo meets illustration.
const MET_BY: Record<string, string[]> = {
  footage: ["footage", "screen"],
  photo: ["photo", "library"],
  illustration: ["photo", "library", "logo"],
  character: ["library"],
};
const lower = (xs?: readonly unknown[]) => (xs ?? []).map((x) => String(x).toLowerCase());

function assetKinds(assets: BeatAsk["assets"]): string[] | null {
  if (assets === undefined || assets === null) return null; // not given: needs are not filtered
  if (assets === "none") return [];
  if (Array.isArray(assets)) return lower(assets);
  return lower(Object.keys(assets));
}
const unmet = (needs: string[], have: string[]) => lower(needs).filter((n) => MET_BY[n] && !MET_BY[n].some((a) => have.includes(a)));

// Distance from a beat's length to a recipe's play length: none fits anything; "1.5 s+" fits from 1.5 up.
function distance(duration: ArsenalRecipe["duration"], want?: number): number {
  if (want === undefined || duration === null || duration === undefined) return 0;
  const m = String(duration).match(/(\d+(?:\.\d+)?)\s*(?:s)?\s*(\+)?/);
  if (!m) return 0;
  const d = parseFloat(m[1]);
  return m[2] ? Math.max(0, d - want) : Math.abs(d - want);
}

/** Per beat: a ranked shortlist. Refuses another vocab or an unknown job id; never guesses one. */
export function findTechniques(catalog: ArsenalCatalog, ask: BeatAsk): FindAnswer {
  if (ask.vocab !== catalog.vocab) throw new ArsenalRefusal(`refused: ask is vocab ${ask.vocab} but the catalog is ${catalog.vocab}`);
  for (const j of [ask.job, ...(ask.support ?? [])]) {
    if (!catalog.jobs.includes(j)) throw new ArsenalRefusal(`refused: unknown job "${j}"; valid ids: ${catalog.jobs.join(", ")}`);
  }
  const support = ask.support ?? [];
  const mood = lower(ask.mood);
  const have = assetKinds(ask.assets);
  const exclude = new Set(ask.exclude ?? []);
  const limit = ask.limit ?? 5;

  // Job match tier: 0 primary job, 1 the asked job is one of its supports, 2 it serves one of the beat's support jobs.
  const tier = (r: ArsenalRecipe): number | null =>
    r.job === ask.job ? 0 : r.support.includes(ask.job) ? 1 : [r.job, ...r.support].some((j) => j !== null && support.includes(j)) ? 2 : null;
  // A variant is never a candidate on its own: its parent stands for it and lists it (variants).
  const byJob = catalog.entries.filter((r) => (r.kind === "technique" || r.kind === "piece") && !r.variant_of && tier(r) !== null && !exclude.has(r.id));

  const pass = (r: ArsenalRecipe, loose: string[]) =>
    (loose.includes("status") || ask.constraints?.status === "any" || r.status === "proven")
    && (loose.includes("needs") || have === null || unmet(r.needs, have).length === 0);

  let relaxed: string[] = [];
  let hits = byJob.filter((r) => pass(r, relaxed));
  for (const step of ["status", "needs"]) {
    if (hits.length || !byJob.length) break;
    relaxed = [...relaxed, step];
    hits = byJob.filter((r) => pass(r, relaxed));
  }

  const overlap = (r: ArsenalRecipe) => lower(r.mood).filter((m) => mood.includes(m));
  const ranked = hits
    // Pieces first: when a piece and a written recipe both fit the job, the piece is what to build with.
    .map((r) => ({ r, key: [r.kind === "piece" ? 0 : 1, tier(r)!, r.status === "proven" ? 0 : 1, -r.taught_by, -overlap(r).length, distance(r.duration, ask.duration)] }))
    .sort((a, b) => { for (let i = 0; i < a.key.length; i++) if (a.key[i] !== b.key[i]) return a.key[i] - b.key[i]; return 0; })
    .slice(0, limit);

  const fit = (r: ArsenalRecipe) => {
    const t = tier(r);
    const job = t === 0 ? `primary job ${ask.job}` : t === 1 ? `supports ${ask.job}` : `serves support job ${[r.job, ...r.support].find((j) => j !== null && support.includes(j))}`;
    const missing = have === null ? [] : unmet(r.needs, have);
    const needs = !r.needs.length ? "needs nothing"
      : missing.length ? `needs ${missing.join(", ")}, not on hand`
        : have === null ? `needs ${r.needs.join(", ")}` : `needs met: ${r.needs.join(", ")}`;
    const m = overlap(r);
    return [r.kind === "piece" ? "piece: runnable code, get returns its call" : null, job, needs, m.length ? `mood: ${m.join(", ")}` : mood.length ? "no mood overlap" : null,
      r.taught_by > 1 ? `taught ${r.taught_by} times` : null, r.status === "proven" ? "proven" : "unproven, needs a test build first"]
      .filter(Boolean).join("; ");
  };

  const out: FindAnswer = {
    vocab: catalog.vocab, version: catalog.version,
    results: ranked.map(({ r }) => ({
      id: r.id, revision: r.revision, name: r.name, line: r.line, status: r.status, needs: r.needs,
      duration: r.duration, motion: r.motion, still: r.still?.path ?? null, section: r.section, fit: fit(r),
      ...(r.variants?.length ? { variants: r.variants } : {}),
      ...(r.kind === "piece" && r.call ? { kind: "piece" as const, call: r.call.signature } : {}),
    })),
  };
  if (relaxed.length && out.results.length) out.relaxed = relaxed;
  return out;
}

// ---------- across levels: provides and browse ----------

/** "material: glass" -> ["material", "glass"]; "depth" -> ["depth", null]; anything else null. */
export function parseProvides(p: string): [string, string | null] | null {
  const m = /^\s*([a-z-]+)\s*(?::\s*([a-z0-9-]+)\s*)?$/.exec(String(p).toLowerCase());
  return m ? [m[1], m[2] ?? null] : null;
}
const showProvides = ([k, w]: [string, string | null]) => (w ? `${k}: ${w}` : k);

/** Refuses a provides ask outside the catalog's vocabulary, naming what is valid; never guesses. */
function askedProvides(catalog: ArsenalCatalog, asked: string[] | undefined): Array<[string, string | null]> {
  const vocab = catalog.provides ?? {};
  return (asked ?? []).map((p) => {
    const k = parseProvides(p);
    if (!k) throw new ArsenalRefusal(`refused: provides "${p}" is not "key" or "key: word"; keys: ${Object.keys(vocab).join(", ")}`);
    if (!vocab[k[0]]) throw new ArsenalRefusal(`refused: unknown provides key "${k[0]}"; valid keys: ${Object.keys(vocab).join(", ")}`);
    if (k[1] && !vocab[k[0]].includes(k[1])) throw new ArsenalRefusal(`refused: unknown ${k[0]} word "${k[1]}"; valid ${k[0]} words: ${vocab[k[0]].join(", ")}`);
    return k;
  });
}
function checkLevel(level: string | undefined): Level | undefined {
  if (level === undefined) return undefined;
  if (!(LEVELS as readonly string[]).includes(level)) throw new ArsenalRefusal(`refused: unknown level "${level}"; valid levels: ${LEVELS.join(", ")}`);
  return level as Level;
}
export const atLevel = (e: ArsenalEntry, level: Level) => e.level === level || (e.also_level ?? []).includes(level);
/** The asked provides an entry gives: a bare key matches any word under it. */
function matched(e: ArsenalEntry, asked: Array<[string, string | null]>): string[] {
  const own = e.provides.map(parseProvides).filter((x): x is [string, string | null] => x !== null);
  return asked.filter(([k, w]) => own.some(([ok, ow]) => ok === k && (w === null || ow === w))).map(showProvides);
}
const levelText = (e: ArsenalEntry) => [e.level, ...(e.also_level ?? []).map((l) => `also ${l}`)].join(", ");

// ---------- plain words ----------

// Words that say nothing about what an entry does ("something that turns over" asks for "turn" and "over").
const STOP = new Set(("a an the this that these those it its something anything thing things some any one i me my we our you your " +
  "need needs want wants make makes made get gets can could will would should like into onto to of for and or but with on in at by " +
  "is are be was were been from as so then than which what when where who how do does please just more very").split(" "));
/** A word cut to its stem, so turns, turned and turning all read "turn" and flips and flipping read "flip". */
export function stem(word: string): string {
  let w = word.toLowerCase().replace(/[^a-z0-9]/g, "");
  if (w.length > 4 && w.endsWith("ies")) w = `${w.slice(0, -3)}y`;
  else if (w.length > 4 && w.endsWith("ing")) w = w.slice(0, -3);
  else if (w.length > 3 && w.endsWith("ed")) w = w.slice(0, -2);
  else if (w.length > 3 && w.endsWith("s") && !w.endsWith("ss")) w = w.slice(0, -1);
  if (w.length > 3 && w.at(-1) === w.at(-2) && !/[aeiouls]/.test(w.at(-1)!)) w = w.slice(0, -1); // flipp -> flip
  if (w.length > 3 && w.endsWith("e")) w = w.slice(0, -1); // piece/pieces, place/placed
  return w;
}
const stems = (text: string) => text.split(/[^A-Za-z0-9]+/).filter(Boolean).map(stem);
/** The stems a plain-words ask looks for: common words dropped, each stem once. */
export function queryWords(query: string): string[] {
  return [...new Set(query.split(/[^A-Za-z0-9]+/).filter((w) => w && !STOP.has(w.toLowerCase())).map(stem).filter((w) => w.length > 1))];
}
/** The asked stems an entry's own words carry: its id, name, line, what it is used for, its jobs and provides. */
function wordsMatched(e: ArsenalEntry, words: string[]): string[] {
  if (!words.length) return [];
  const own = new Set(stems([e.id, e.name, e.line, e.use_for ?? "", e.job ?? "", ...e.support, ...e.provides].join(" ")));
  return words.filter((w) => own.has(w));
}

export type ProvidesAsk = {
  level?: string; provides?: string[]; query?: string; shelf?: "shipped" | "user"; status?: "proven" | "any"; exclude?: string[]; limit?: number;
};
export type EntrySummary = Pick<ArsenalEntry, "id" | "revision" | "level" | "also_level" | "name" | "line" | "status" | "kind" | "provides" | "needs" | "cost" | "section">
  & { still: string | null; fit: string; variants?: string[]; use_for?: string; call?: string };
export type ProvidesAnswer = { vocab: string; version: string; results: EntrySummary[]; relaxed?: string[]; words?: string[] };

/**
 * Entries across levels by what they provide, by level and/or by plain words (query). Proven only unless status is
 * any (relaxed when that leaves nothing). With query, only the entries that carry the most of its words are kept
 * (every word when any entry has them all, else "words" is named in relaxed), pieces first among them. Then ranked by
 * how many asked provides an entry gives, then with a still before without, then catalog order; never by a
 * preferred look. A variant stands behind its parent.
 */
export function findByProvides(catalog: ArsenalCatalog, ask: ProvidesAsk): ProvidesAnswer {
  const level = checkLevel(ask.level);
  const asked = askedProvides(catalog, ask.provides);
  const words = ask.query === undefined ? [] : queryWords(ask.query);
  if (ask.query !== undefined && !words.length) throw new ArsenalRefusal(`refused: query "${ask.query}" has no words to look for once common words are dropped; say what the beat does, e.g. "turns over" or "glass floor"`);
  if (!level && !asked.length && !words.length) throw new ArsenalRefusal("refused: find needs a job, a level, provides or a query");
  const exclude = new Set(ask.exclude ?? []);
  const limit = ask.limit ?? 5;
  let pool = catalog.entries.filter((e) => !e.variant_of && !exclude.has(e.id)
    && (!level || atLevel(e, level)) && (!ask.shelf || e.shelf === ask.shelf) && (!asked.length || matched(e, asked).length > 0));
  let relaxed: string[] = [];
  if (words.length) {
    const best = Math.max(0, ...pool.map((e) => wordsMatched(e, words).length));
    pool = best ? pool.filter((e) => wordsMatched(e, words).length === best) : [];
    if (best && best < words.length) relaxed = ["words"];
  }
  let hits = pool.filter((e) => ask.status === "any" || e.status === "proven");
  if (!hits.length && pool.length) { relaxed = [...relaxed, "status"]; hits = pool; }
  const ranked = hits
    .map((e, i) => ({ e, key: [words.length && e.kind === "piece" ? 0 : 1, -matched(e, asked).length, e.still ? 0 : 1, i] }))
    .sort((a, b) => { for (let i = 0; i < a.key.length; i++) if (a.key[i] !== b.key[i]) return a.key[i] - b.key[i]; return 0; })
    .slice(0, limit);
  const out: ProvidesAnswer = {
    vocab: catalog.vocab, version: catalog.version,
    ...(words.length ? { words } : {}),
    results: ranked.map(({ e }) => {
      const m = matched(e, asked);
      const w = wordsMatched(e, words);
      return {
        id: e.id, revision: e.revision, level: e.level, ...(e.also_level?.length ? { also_level: e.also_level } : {}),
        name: e.name, line: e.line, status: e.status, kind: e.kind, provides: e.provides, needs: e.needs, cost: e.cost,
        still: e.still?.path ?? null, section: e.section,
        ...(e.kind === "piece" && e.call ? { use_for: e.use_for, call: e.call.signature } : {}),
        fit: [e.kind === "piece" ? "piece: runnable code, get returns its call" : null, levelText(e),
          w.length ? `words: ${w.join(", ")} of ${words.join(", ")}` : null,
          m.length ? `provides ${m.join(", ")}` : null, e.status === "proven" ? "proven" : "unproven, needs a test build first",
          e.still ? null : `no still: ${e.no_still ?? "none shipped"}`].filter(Boolean).join("; "),
        ...(e.variants?.length ? { variants: e.variants } : {}),
      };
    }),
  };
  if (relaxed.length && out.results.length) out.relaxed = relaxed;
  return out;
}

export type BrowseAsk = { level?: string; provides?: string[]; shelf?: "shipped" | "user"; page?: number; page_size?: number; include_unpictured?: boolean };
export type BrowseTile = { n: number; id: string; name: string; level: Level; also_level?: Level[]; kind?: "piece"; role?: "house" | "example"; block?: string; provides: string[]; status: ArsenalEntry["status"]; no_still?: string };
export type BrowsePage = {
  vocab: string; version: string; level: Level | "all"; provides?: string[]; page: number; pages: number; page_size: number; total: number;
  hidden_without_still: number; tiles: BrowseTile[];
};
export const BROWSE_PAGE = 12;
export const BROWSE_PAGE_MAX = 24;

/**
 * One page of a level (or every level, styles first) as tiles: id, name and provides for each, in catalog order.
 * Entries with no still are hidden unless include_unpictured, and counted. A variant stands behind its parent.
 */
export function browseCatalog(catalog: ArsenalCatalog, ask: BrowseAsk = {}): BrowsePage {
  const level = checkLevel(ask.level);
  const asked = askedProvides(catalog, ask.provides);
  const size = Math.min(Math.max(1, Math.floor(ask.page_size ?? BROWSE_PAGE)), BROWSE_PAGE_MAX);
  const order = level ? [level] : [...LEVELS];
  const seen = new Set<string>();
  const all: ArsenalEntry[] = [];
  for (const l of order) for (const e of catalog.entries) {
    if (seen.has(e.id) || e.variant_of || !atLevel(e, l)) continue;
    if (ask.shelf && e.shelf !== ask.shelf) continue;
    if (asked.length && !matched(e, asked).length) continue;
    seen.add(e.id); all.push(e);
  }
  const shown = ask.include_unpictured ? all : all.filter((e) => e.still);
  const pages = Math.max(1, Math.ceil(shown.length / size));
  const page = Math.min(Math.max(1, Math.floor(ask.page ?? 1)), pages);
  const tiles = shown.slice((page - 1) * size, page * size).map((e, i) => ({
    n: (page - 1) * size + i + 1, id: e.id, name: e.name, level: e.level, ...(e.also_level?.length ? { also_level: e.also_level } : {}),
    ...(e.kind === "piece" ? { kind: "piece" as const } : {}), ...(e.role ? { role: e.role } : {}), ...(e.block ? { block: e.block } : {}), provides: e.provides, status: e.status, ...(e.still ? {} : { no_still: e.no_still ?? "none shipped" }),
  }));
  return {
    vocab: catalog.vocab, version: catalog.version, level: level ?? "all", ...(asked.length ? { provides: asked.map(showProvides) } : {}),
    page, pages, page_size: size, total: shown.length, hidden_without_still: all.length - shown.length, tiles,
  };
}

// ---------- reading the shipped arsenal ----------

export function loadCatalog(root = LIBRARY): ArsenalCatalog {
  return JSON.parse(readLibraryEntry("arsenal-catalog", root).content) as ArsenalCatalog;
}

type JobsFile = { version: string; groups: Record<string, string>; tags: Record<string, string>; jobs: Array<{ id: string; group: string; name: string; definition: string; example?: string }> };

/** The job vocabulary (each job's id, group, name and one-line definition, and the two tags that are not jobs), the levels and the provides vocabulary. */
export function listJobs(root = LIBRARY) {
  const file = JSON.parse(readLibraryEntry("arsenal-jobs", root).content) as JobsFile;
  const catalog = loadCatalog(root);
  return {
    vocab: `jobs-v${String(file.version).replace(/^v/, "")}`,
    groups: file.groups,
    jobs: file.jobs.map(({ id, group, name, definition }) => ({ id, group, name, definition })),
    tags: file.tags,
    levels: catalog.levels ?? LEVELS,
    provides: catalog.provides ?? {},
  };
}

/**
 * How to call a piece, not prose: the line that loads it (with this install's absolute library path), the call, its
 * options, what it returns, a short example, the pieces it works with and its notes. The piece's file is read through
 * the manifest, so a file that changed since the catalog was built is refused, never run.
 */
export function pieceReply(r: ArsenalEntry, warning: string | null, catalog: ArsenalCatalog, root = LIBRARY): string {
  const call = r.call;
  if (!call) throw new Error(`the arsenal is inconsistent: piece ${r.id} has no call`);
  readLibraryEntry(r.section.document, root);
  const dir = path.join(realpathSync(root), "pieces");
  // The load line loads every piece the example calls, so the example runs as written.
  const others = catalog.entries.filter((e) => e.kind === "piece" && e.call && e.id !== r.id && call.example.includes(`PCS.${e.call.load}(`)).map((e) => e.call!.load);
  const load = `$.evalFile(File(${JSON.stringify(path.join(dir, "pcs-core.jsx"))})); ${[...others, call.load].map((n) => `PCS.need('${n}');`).join(" ")}`;
  const version = catalog.version;
  return [
    `ae_arsenal piece ${r.id}@${r.revision} (${r.status}; recipe level, runnable code; renderer ${r.cost.renderer}; catalog ${version}; file library/pieces/${call.load}.jsx, readable with ae_library ${r.section.document})`,
    warning,
    `${r.name}: ${r.line}`,
    r.use_for ? `use it for: ${r.use_for}` : null,
    `jobs: ${[r.job, ...r.support].filter(Boolean).join(", ")}; provides: ${r.provides.join("; ") || "nothing listed"}; needs: ${r.needs.length ? r.needs.join(", ") : "nothing"}`,
    "",
    "load (in eval.run with rollback: false; the house style is on until PCS.use picks another, by style block name or a style object):",
    `  ${load}`,
    `call: ${call.signature}`,
    ...(call.options.length ? ["options:", ...call.options.map((o) => `  ${o.name}: ${o.text}`)] : []),
    call.returns ? `returns: ${call.returns}` : null,
    "example:",
    ...call.example.split("\n").map((l) => `  ${l}`),
    `works with: ${r.composes.length ? r.composes.join(", ") : "nothing recorded yet"}`,
    ...(r.requires?.length ? [`loads itself: ${r.requires.join(", ")}`] : []),
    ...call.notes.map((n) => `note: ${n}`),
  ].filter((l) => l !== null).join("\n");
}

/** One recipe's full text as a reply: a header line with id@revision, a warning when a pinned revision differs. */
export function recipeReply(id: string, revision: string | undefined, root = LIBRARY): string {
  const catalog = loadCatalog(root);
  const r = catalog.entries.find((x) => x.id === id);
  if (!r) throw new ArsenalRefusal(`refused: unknown id "${id}"; ae_arsenal browse and find return ids`);
  const warning = revision !== undefined && revision !== r.revision
    ? `WARNING: pinned revision ${revision}; the shipped revision is ${r.revision}. The ${r.kind === "style" ? "entry" : r.kind === "piece" ? "piece" : "recipe"} changed since it was pinned: this is the shipped ${r.kind === "piece" ? "call" : "text"}, not the pinned one. Check it still fits the beat.`
    : null;
  if (r.kind === "piece") return pieceReply(r, warning, catalog, root);
  if (r.kind === "style") {
    const head = `ae_arsenal ${r.level} ${r.id}@${r.revision} (${levelText(r)}${r.role ? `; ${r.role === "house" ? "the house style" : "an example, not a house look"}` : ""}; ${r.status}; shelf ${r.shelf}; catalog ${catalog.version}; its document is library document ${r.section.document}, also readable with ae_library)`;
    const blockDoc = r.block ? `pieces-style-${r.block}` : null;
    const pieces = r.block ? [
      `in pieces: PCS.use('${r.block}') after loading pieces/pcs-core.jsx${r.default ? " (the default: pieces use it when no style is picked)" : ""}; the values are in library document ${blockDoc}`,
      ...(r.open ?? []).map((o) => `not in it yet: ${o}`),
    ] : [];
    const facts = [
      ...pieces,
      `provides: ${r.provides.join("; ")}`,
      `needs: ${r.needs.length ? r.needs.join(", ") : "nothing"}`,
      `cost: renderer ${r.cost.renderer}${r.cost.seconds_per_frame !== undefined ? `, ${r.cost.seconds_per_frame} s per frame (${r.cost.measured ?? "measured"})` : ""}`,
      `composes: ${r.composes.length ? r.composes.join(", ") : "none recorded yet"}`,
      ...(r.good_for ? [`good for: ${r.good_for}`] : []),
    ];
    const block = blockDoc && blockDoc !== r.section.document ? ["", `style block for pieces (${blockDoc}):`, readLibraryEntry(blockDoc, root).content.trimEnd()] : [];
    return [head, warning, ...facts, "", libraryDocumentReply(r.section.document, undefined, root), ...block].filter((l) => l !== null).join("\n");
  }
  const { content } = readLibraryEntry(r.section.document, root);
  const section = content.split(/^(?=## )/m).find((s) => s.startsWith(`## ${r.section.heading ?? ""}\n`) && new RegExp(`^id: ${r.id}$`, "m").test(s));
  if (!section) throw new Error(`the arsenal is inconsistent: ${r.section.document} has no section for ${r.id}`);
  const head = `ae_arsenal recipe ${r.id}@${r.revision} (${r.status}, ${r.kind}; ${r.variant_of ? `variant of ${r.variant_of}; ` : ""}${catalog.vocab}, catalog ${catalog.version}; from library document ${r.section.document})`;
  const provides = r.provides?.length ? `provides: ${r.provides.join("; ")}` : null;
  return [head, warning, provides, "", section.trimEnd()].filter((l) => l !== null).join("\n");
}

/** A still's bytes, read inside the library and checked against the catalog's hash. */
function readStill(still: { path: string; sha256: string }, root = LIBRARY): Buffer {
  const base = realpathSync(root);
  const file = realpathSync(path.resolve(base, still.path));
  const rel = path.relative(base, file);
  if (!rel || rel.startsWith("..") || path.isAbsolute(rel)) throw new Error("Arsenal still escapes the library");
  const bytes = readFileSync(file);
  if (createHash("sha256").update(bytes).digest("hex") !== still.sha256) throw new Error(`Arsenal still hash mismatch: ${still.path}`);
  return bytes;
}

function stillContent(r: ArsenalEntry, root = LIBRARY, label?: string): ToolContent[] {
  if (!r.still) return [];
  return [
    { type: "text", text: label ?? `Still of ${r.id} (${r.name}), from our own proof build:` },
    { type: "image", data: readStill(r.still, root).toString("base64"), mimeType: "image/jpeg" },
  ];
}

// ---------- the tool ----------

const providesArg = z.union([z.string(), z.array(z.string())]).optional()
  .describe("browse and find: what an entry must provide, \"key\" or \"key: word\" (e.g. \"material: glass\", \"floor\"), one or a list; action jobs lists the vocabulary");
const askShape = {
  action: z.enum(["browse", "find", "get", "jobs"]).describe("browse: a level as labelled stills, a page at a time; find: a shortlist by job for one beat, or by level, provides and/or plain words across levels; get: any entry by id (a piece answers with its call); jobs: the job and provides vocabularies"),
  level: z.enum(LEVELS).optional().describe("browse and find: style (a look a section can borrow: colour, type, light, material), world (a set a section lives in) or recipe (one technique for one beat; pieces are recipes you run); browse without it shows every level, styles first"),
  provides: providesArg,
  query: z.string().optional().describe("find: what the beat needs in plain words (e.g. \"something that turns over\"); returns the entries that carry the most of its words, pieces first"),
  shelf: z.enum(["shipped", "user"]).optional().describe("browse and find: only entries from this shelf"),
  page: z.number().int().positive().optional().describe("browse: which page, from 1"),
  page_size: z.number().int().positive().max(BROWSE_PAGE_MAX).optional().describe(`browse: tiles per page, default ${BROWSE_PAGE}`),
  include_unpictured: z.boolean().optional().describe("browse: also list entries with no still (build aids, unproven recipes); hidden by default and counted"),
  vocab: z.string().optional().describe("find: the job vocabulary the beat was written against (e.g. jobs-v1); omitted means the shipped one"),
  job: z.string().optional().describe("find: the beat's job id, from action jobs (e.g. add-depth, land-number, hand-over)"),
  support: z.array(z.string()).optional().describe("find: up to two support job ids"),
  duration: z.number().optional().describe("find: the beat's length in seconds"),
  takeaway: z.string().optional().describe("find: what the viewer must get from the beat (carried for the record; not ranked on)"),
  mood: z.array(z.string()).optional().describe("find: mood words, matched softly against each recipe's mood tags"),
  assets: z.union([z.record(z.string(), z.unknown()), z.array(z.string()), z.literal("none")]).optional()
    .describe("find: what the beat has on hand, by kind (footage, screen, photo, logo, voice, library, type), or \"none\"; omitted means needs are not filtered"),
  constraints: z.object({
    aspect: z.string().optional(), theme: z.string().optional(), palette: z.string().optional(),
    status: z.enum(["proven", "any"]).optional().describe("proven (the default) or any, to let unproven entries through"),
  }).optional(),
  exclude: z.array(z.string()).optional().describe("find: ids already used or ruled out"),
  limit: z.number().int().positive().max(20).optional().describe("find: how many candidates, default 5"),
  id: z.string().optional().describe("get: an id from browse or find, at any level"),
  revision: z.string().optional().describe("get: the revision the brief pinned; a different shipped revision is answered with a warning"),
};
const listOf = (p: string | string[] | undefined) => (p === undefined ? undefined : Array.isArray(p) ? p : [p]);

export const arsenalTool = defineTool({
  name: "ae_arsenal", title: "Library: styles, worlds, recipes and pieces", group: "document", effect: "read", blockedInReadOnly: false,
  description: "The library at three levels, each entry with a still from our own proof build and what it provides: styles (a look a section can borrow: colour, type, light, material), worlds (a set a section lives in: floor, light, environment, materials) and recipes (one technique for one beat). Among the recipes, pieces are runnable code: one file each, called by name, built and lit (thickness, light, shadow, overshoot) but carrying no look of their own. " +
    "action browse shows a level as labelled stills, a page at a time (level, provides, shelf, page, page_size); start a brief there. " +
    "action find with job returns a ranked shortlist for one beat, pieces first, then written recipes (job, and optionally support, duration, mood, assets, constraints.status, exclude, limit; proven only unless constraints.status is any; relaxed names any filter loosened when nothing passed; never another job; a candidate taught in other ways lists their ids as variants). " +
    "action find with query (plain words, e.g. \"something that turns over\"), level and/or provides (e.g. \"material: glass\", \"floor: gloss-dark\") returns entries across levels, pieces first when the words fit one. " +
    "An unknown job, level or provides word is refused with the valid ones: pick one, never invent one. action jobs lists the job and provides vocabularies. " +
    "action get takes any id (and the pinned revision) with its still: a piece answers with its call (the load line, signature, options, returns and a short example) to run in eval.run; a recipe with its text; a style or world with its document. Offline; no After Effects needed.",
  inputShape: askShape,
  handler: async (args): Promise<ToolResult> => {
    try {
      if (args.action === "jobs") return jsonResult(listJobs());
      const catalog = loadCatalog();
      const byId = new Map(catalog.entries.map((r) => [r.id, r]));
      if (args.action === "get") {
        if (!args.id) return errorResult("INVALID_ARGS", "get needs id: an id from ae_arsenal browse or find");
        const text = recipeReply(args.id, args.revision);
        return { content: [{ type: "text", text }, ...stillContent(byId.get(args.id)!)], isError: false };
      }
      if (args.action === "browse") {
        const page = browseCatalog(catalog, { level: args.level, provides: listOf(args.provides), shelf: args.shelf, page: args.page, page_size: args.page_size, include_unpictured: args.include_unpictured });
        const label = (t: BrowseTile) => `Tile ${t.n}: ${t.id} · ${t.name} · ${[t.level, ...(t.also_level ?? []).map((l) => `also ${l}`)].join(", ")}${t.kind === "piece" ? " · piece (runnable; get returns its call)" : ""}${t.role === "house" ? " · the house style, the default for pieces" : t.role === "example" ? " · an example style, not a house look" : ""}${t.block ? ` · pieces: PCS.use('${t.block}')` : ""} · provides ${t.provides.length ? t.provides.join(", ") : "nothing listed"}${t.status === "proven" ? "" : " · unproven"}`;
        const images = page.tiles.flatMap((t) => (byId.get(t.id)!.still ? stillContent(byId.get(t.id)!, LIBRARY, label(t)) : [{ type: "text" as const, text: `${label(t)} · no still: ${t.no_still}` }]));
        const next = page.page < page.pages ? ` Next: page ${page.page + 1}.` : "";
        const head = `ae_arsenal browse: ${page.level === "all" ? "every level, styles first" : `level ${page.level}`}${page.provides ? `, providing ${page.provides.join(" or ")}` : ""}; page ${page.page} of ${page.pages}, tiles ${page.tiles.length ? `${page.tiles[0].n} to ${page.tiles.at(-1)!.n}` : "none"} of ${page.total}${page.hidden_without_still ? `; ${page.hidden_without_still} without a still hidden (include_unpictured lists them)` : ""}.${next} Read one with get.`;
        return { content: [{ type: "text", text: `${head}\n${JSON.stringify({ ok: true, ...page }, null, 2)}` }, ...images], isError: false };
      }
      if (!args.job) {
        if (args.level === undefined && args.provides === undefined && args.query === undefined) return errorResult("INVALID_ARGS", "find needs job (a job id from ae_arsenal action jobs), or a query in plain words, level and/or provides", { hint: "call ae_arsenal with action jobs for the valid job ids and provides words" });
        const answer = findByProvides(catalog, { level: args.level, provides: listOf(args.provides), query: args.query, shelf: args.shelf, status: args.constraints?.status, exclude: args.exclude, limit: args.limit });
        const images = answer.results.flatMap((c) => stillContent(byId.get(c.id)!));
        return { content: [{ type: "text", text: JSON.stringify({ ok: true, ...answer }, null, 2) }, ...images], isError: false };
      }
      if (args.level !== undefined || args.provides !== undefined || args.shelf !== undefined || args.query !== undefined) {
        return errorResult("INVALID_ARGS", "find asks by job for one beat, or by query, level and provides across levels, not both: drop job, or drop query, level, provides and shelf");
      }
      const answer = findTechniques(catalog, {
        vocab: args.vocab ?? catalog.vocab, job: args.job, support: args.support, duration: args.duration, takeaway: args.takeaway, mood: args.mood,
        assets: args.assets as BeatAsk["assets"], constraints: args.constraints, exclude: args.exclude, limit: args.limit,
      });
      // Text and images only: a host shown a structured part passes that on instead of the rest (library-parts.ts).
      const images = answer.results.flatMap((c) => stillContent(byId.get(c.id)!));
      return { content: [{ type: "text", text: JSON.stringify({ ok: true, ...answer }, null, 2) }, ...images], isError: false };
    } catch (e) {
      if (e instanceof ArsenalRefusal) return errorResult("INVALID_ARGS", e.message);
      return errorResult("IO", e instanceof Error ? e.message : String(e));
    }
  },
});
